class BSTNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def modify(root):
    total = [0]

    def reverse_inorder(node):
        if node is None:
            return
        reverse_inorder(node.right)
        total[0] += node.value
        node.value = total[0]
        reverse_inorder(node.left)

    reverse_inorder(root)
    return root
